<?php /** @var array $post */ $blogCardImagePath=(string)($post['cover_image']??'');$blogCardImage=public_image_thumbnail($blogCardImagePath);$blogCardSrcset=public_image_srcset($blogCardImagePath); ?>
<article class="blog-card blog-card--content">
<a class="blog-card__media" href="<?=e(blog_post_url($post))?>"><?php if(!empty($post['cover_image'])):?><img src="<?=e($blogCardImage)?>" <?=$blogCardSrcset!==''?'srcset="'.e($blogCardSrcset).'" sizes="(max-width: 980px) calc(100vw - 44px), 380px"':''?> alt="<?=e($post['cover_alt']?:$post['title'])?>" loading="lazy" decoding="async" width="720" height="405"><?php else:?><span>راهنمای خرید</span><?php endif?></a>
<div class="blog-body"><div class="blog-card__meta"><a href="<?=e(app_url('blog.php?category='.rawurlencode((string)$post['category_slug'])))?>"><?=e($post['category_name'])?></a><span><?=e(jalali_date_format($post['published_at']))?></span></div><h3><a href="<?=e(blog_post_url($post))?>"><?=e($post['title'])?></a></h3><p><?=e(blog_excerpt($post,150))?></p><div class="blog-card__footer"><span><?=fa_number(blog_reading_minutes((string)$post['content']))?> دقیقه مطالعه</span><a href="<?=e(blog_post_url($post))?>">ادامه مطلب ←</a></div></div>
</article>
